package com.ptms.controller;import com.ptms.service.AuthService;import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api") public class AuthController{private final AuthService s;public AuthController(AuthService s){this.s=s;}@PostMapping("/auth/login") public Map<String,Object> login(@RequestBody Map<String,String> q,HttpSession session){Map<String,Object>u=s.login(q.get("username"),q.get("password"));session.setAttribute("username",u.get("username"));session.setAttribute("role",String.valueOf(u.get("role")));return u;}@PostMapping("/auth/logout") public void logout(HttpSession s){s.invalidate();}@PostMapping("/auth/forgot-password") public Map<String,String> forgot(@RequestBody Map<String,String> q){return Map.of("message",s.forgot(q.get("email")));}@PostMapping("/auth/reset-password") public void reset(@RequestBody Map<String,String>q){s.reset(q.get("token"),q.get("newPassword"));}@PostMapping("/auth/change-password") public void change(@RequestBody Map<String,String>q){s.change(q.get("username"),q.get("currentPassword"),q.get("newPassword"));}@GetMapping("/users") public List<Map<String,Object>> users(){return s.users();}@PostMapping("/users") public Map<String,Object> create(@RequestBody Map<String,Object>q){return s.save(null,q);}@PutMapping("/users/{id}") public Map<String,Object> update(@PathVariable Long id,@RequestBody Map<String,Object>q){return s.save(id,q);}@DeleteMapping("/users/{id}") public void delete(@PathVariable Long id){s.delete(id);}}
